package org.threeten.extra.chrono;

import static org.junit.jupiter.api.Assertions.assertThrows;

import java.time.DateTimeException;
import java.time.Month;

import org.junit.jupiter.api.Test;

@SuppressWarnings({ "static-method" })
public class TestPaxChronology_test_adjust_toMonth {

    /**
     * A {@link Month} is an ISO-calendar value, so it cannot be used to adjust a
     * {@link PaxDate}. Attempting to do so must fail with a {@link DateTimeException}.
     */
    @Test
    public void test_adjust_toMonth() {
        PaxDate paxDate = PaxDate.of(2000, 1, 4);

        assertThrows(DateTimeException.class, () -> paxDate.with(Month.APRIL));
    }
}
